/** The insured things the MHPCO knows, and the price-list facts that both the
 *  premium office and the claims office read off the same catalogue entry.
 *  Neither side owns this knowledge: a new item type is one catalogue change,
 *  not a change to how premiums or payouts are decided. */

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

/** One row of the MHPCO price list: everything the office has decided about an
 *  item type. Insurance value and base premium are quoted together, per type,
 *  and are revised together when the office reprices a type. */
interface CatalogueEntry {
  insuranceValue: number;
  basePremium: number;
}

/** Every component -- rune, moonstone -- is insured for the same sum and
 *  carries the same base premium, independent of which component it is. */
const COMPONENT: CatalogueEntry = { insuranceValue: 250, basePremium: 25 };

/** The MHPCO price list. Every item type the office recognizes appears here
 *  exactly once, so a new type is one row, never two half-entries. */
const PRICE_LIST: Record<string, CatalogueEntry> = {
  sword: { insuranceValue: 1000, basePremium: 100 },
  amulet: { insuranceValue: 600, basePremium: 60 },
  staff: { insuranceValue: 800, basePremium: 80 },
  potion: { insuranceValue: 400, basePremium: 40 },
  rune: COMPONENT,
  moonstone: COMPONENT,
};

/** The price list's entry for an insured item. The MHPCO insures only what its
 *  price list names, so a type the list does not carry is refused here rather
 *  than priced: the office has no insurance value and no base premium to quote
 *  for it, and both counters must refuse it for the same one reason. */
function catalogueEntry(item: Item): CatalogueEntry {
  const entry = PRICE_LIST[item.type];
  if (entry === undefined) {
    throw new Error(`the MHPCO price list knows no item of type "${item.type}"`);
  }
  return entry;
}

/** The sum the MHPCO insures an item for, per the price list. */
export function insuranceValue(item: Item): number {
  return catalogueEntry(item).insuranceValue;
}

/** The MHPCO price list's base premium for an insured item. */
export function basePremium(item: Item): number {
  return catalogueEntry(item).basePremium;
}

/** Two items are "alike" when they share this key. The MHPCO reads "alike"
 *  as *the same type* -- a rune is alike another rune, but not a moonstone. */
export function alikeKey(item: Item): string {
  return item.type;
}

src/premium.ts.source:
/** The premium office: what the MHPCO charges to take a list of items on risk.
 *  Every decision here belongs to the tariff -- the price list, the building
 *  block, the risk surcharges, the customer's standing, the processing fee, and
 *  the rounding that falls the office's way. It changes when the tariff is
 *  revised, independently of how claims are settled. */

import { alikeKey, basePremium, type Item } from "./item-catalog.js";
import { amountCollectedInMHPCOsFavour } from "./rounding.js";

export interface Customer {
  yearsWithMHPCO: number;
}

/** The MHPCO price list offers a building block of 3 alike items at a
 *  special base premium instead of the sum of the per-item prices. The
 *  price list states the rule for components; the office has not yet ruled
 *  on whether a block of 3 alike main items is granted the same price. */
const BUILDING_BLOCK_SIZE = 3;
const BUILDING_BLOCK_BASE_PREMIUM = 60;

const CURSE_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
const LOYALTY_YEARS_THRESHOLD = 2;
const LOYALTY_DISCOUNT_RATE = 0.2;
const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const PROCESSING_FEE = 5;

/** Whether a group of alike items qualifies for the special building-block
 *  price. The MHPCO grants the block only for a group of exactly 3 -- a
 *  fourth alike item forfeits the special price for the whole group. */
function formsBuildingBlock(alikeItems: Item[]): boolean {
  return alikeItems.length === BUILDING_BLOCK_SIZE;
}

/** The base premium the price list charges for one group of alike items:
 *  the special block price when the group forms a building block, otherwise
 *  the per-item price of every item in the group. */
function alikeGroupBasePremium(alikeItems: Item[]): number {
  if (formsBuildingBlock(alikeItems)) {
    return BUILDING_BLOCK_BASE_PREMIUM;
  }
  return alikeItems.reduce((sum, item) => sum + basePremium(item), 0);
}

/** The items of a quote, partitioned into groups of alike items. */
function groupAlikeItems(items: Item[]): Item[][] {
  const groups = new Map<string, Item[]>();
  for (const item of items) {
    const key = alikeKey(item);
    const alike = groups.get(key) ?? [];
    alike.push(item);
    groups.set(key, alike);
  }
  return [...groups.values()];
}

/** The policy base premium: the sum of the base premiums of all insured
 *  items, before any modifier. */
function policyBasePremium(items: Item[]): number {
  return groupAlikeItems(items).reduce(
    (sum, alikeGroup) => sum + alikeGroupBasePremium(alikeGroup),
    0,
  );
}

/** A cursed item carries a risk surcharge for that item alone, not for the
 *  policy. */
function isCursed(item: Item): boolean {
  return item.cursed === true;
}

/** An item counts as highly enchanted from enchantment level 5 upwards. */
function isHighlyEnchanted(item: Item): boolean {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
}

/** The risk surcharges an item carries on its own base premium. An item may
 *  carry several risks at once, and the MHPCO charges every one of them in
 *  full: the surcharges accumulate, each measured on the item's *unmodified*
 *  base premium, so a cursed and highly enchanted sword pays 50 % + 30 %. */
function itemRiskSurcharge(item: Item): number {
  const base = basePremium(item);
  const curse = isCursed(item) ? base * CURSE_SURCHARGE_RATE : 0;
  const enchantment = isHighlyEnchanted(item) ? base * HIGH_ENCHANTMENT_SURCHARGE_RATE : 0;
  return curse + enchantment;
}

/** The risk surcharges of all insured items. */
function policyRiskSurcharge(items: Item[]): number {
  return items.reduce((sum, item) => sum + itemRiskSurcharge(item), 0);
}

/** How the customer stands with the MHPCO at the moment of this quote: the
 *  length of the business relationship and the number of contracts that
 *  precede this one in the customer's scenario. The policy-wide discounts are
 *  decisions about this standing, not about the insured items. */
interface CustomerStanding {
  customer: Customer;
  previousContracts: number;
}

/** A customer is long-standing from 2 years of business with the MHPCO. */
function isLongStanding(standing: CustomerStanding): boolean {
  return standing.customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
}

/** Every contract after the customer's first earns the follow-up discount. */
function isFollowUpContract(standing: CustomerStanding): boolean {
  return standing.previousContracts >= 1;
}

/** The net policy-wide modifier, which the MHPCO charges against the
 *  *unmodified* policy base premium -- item risk surcharges do not raise the
 *  amount these modifiers are measured on. All three policy-wide modifiers are
 *  measured on that same base and accumulated here: the initial assessment
 *  surcharge, the loyalty discount, and the follow-up contract discount. Every
 *  quote is treated as a first insurance and carries the initial assessment
 *  surcharge, regardless of customer history -- so a long-standing customer's
 *  follow-up contract for a new item carries both the surcharge and both
 *  discounts. */
function policyModifierAdjustment(policyBase: number, standing: CustomerStanding): number {
  const firstInsurance = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
  const loyalty = isLongStanding(standing) ? policyBase * LOYALTY_DISCOUNT_RATE : 0;
  const followUp = isFollowUpContract(standing)
    ? policyBase * FOLLOW_UP_CONTRACT_DISCOUNT_RATE
    : 0;
  return firstInsurance - loyalty - followUp;
}

/** The policy premium with all modifiers applied, before the processing fee:
 *  the price-list base premium, plus the risk surcharges the individual items
 *  carry, plus the policy-wide modifiers. */
function modifiedPolicyPremium(items: Item[], standing: CustomerStanding): number {
  const policyBase = policyBasePremium(items);
  return (
    policyBase + policyRiskSurcharge(items) + policyModifierAdjustment(policyBase, standing)
  );
}

/** The settlement the MHPCO bills for a premium it has calculated: the office
 *  adds its processing fee to every premium, last of all and after every
 *  modifier, and then bills the whole G in its own favour. What the
 *  office charges on top of the calculated risk changes independently of how
 *  the premium itself was arrived at; in whose favour the fraction falls is the
 *  office's own tradition, kept in one place for both counters. */
function settledPremium(modifiedPremium: number): number {
  return amountCollectedInMHPCOsFavour(modifiedPremium + PROCESSING_FEE);
}

/** The premium the MHPCO charges a customer for insuring a list of items:
 *  the modified policy premium, settled by the office. */
export function quote(customer: Customer, items: Item[], previousContracts: number): number {
  return settledPremium(modifiedPolicyPremium(items, { customer, previousContracts }));
}

src/rounding.ts.source:
/** How the MHPCO resolves a fraction of a G.
 *
 *  The office's tradition is one rule, not two: *every fraction falls in the
 *  MHPCO's favour*. What favours the office depends on which way the money is
 *  moving -- a fraction of a premium it collects is rounded up, a fraction of a
 *  payout it pays is rounded down -- but the decision behind both is the same
 *  one, and the office would revise it in one act. Keeping the two directions
 *  side by side here is what lets the asymmetry be read as deliberate rather
 *  than met twice, as an accident, in the tariff and in the handbook. */

/** An amount the customer owes the MHPCO, rounded to the whole G in the
 *  office's favour: upwards. */
export function amountCollectedInMHPCOsFavour(amount: number): number {
  return Math.ceil(amount);
}

/** An amount the MHPCO owes the customer, rounded to the whole G in the
 *  office's favour: downwards. */
export function amountPaidInMHPCOsFavour(amount: number): number {
  return Math.floor(amount);
}

src/settlement.ts.source:
/** The claims office: what the MHPCO pays out when an insured item is damaged.
 *  Every decision here belongs to the claims handbook -- the deductible, the
 *  special clauses, the cap on a policy -- and is revised independently of the
 *  tariff that priced the policy. */

import { insuranceValue, type Item } from "./item-catalog.js";
import { amountPaidInMHPCOsFavour } from "./rounding.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface Policy {
  items: Item[];
  /** What the MHPCO has already paid out on this policy against its cap. */
  capConsumed: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

const DEDUCTIBLE_PER_DAMAGE = 100;

/** The MHPCO never pays out more than twice the sum a policy insures. */
const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;

/** From enchantment level 8 upwards the handbook reimburses only half the
 *  damage: powerful enchantments are held to attract their own misfortune.
 *  This is the only clause the handbook reads *down* from full reimbursement,
 *  so it outranks the dragon-material clause whenever both cover an item. */
const HIGH_ENCHANTMENT_CLAUSE_THRESHOLD = 8;
const HIGH_ENCHANTMENT_CLAUSE_SHARE = 0.5;

/** The MHPCO opens a policy over the items a quote covered. */
export function createPolicy(items: Item[]): Policy {
  return { items, capConsumed: 0 };
}

/** The MHPCO bears its deductible against a damage; it never turns the
 *  deductible round into a charge the customer owes the office. A damage
 *  smaller than the deductible is simply not reimbursed. */
function neverACharge(reimbursement: number): number {
  return Math.max(reimbursement, 0);
}

/** Whether the handbook's high-enchantment clause covers a damaged item. */
function fallsUnderHighEnchantmentClause(item: Item): boolean {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAUSE_THRESHOLD;
}

/** The amount of a damage the handbook reimburses, before the deductible is
 *  kept back. Full reimbursement is what the office grants unless a clause cuts
 *  it down, and the high-enchantment clause is the only clause that cuts.
 *
 *  The handbook's dragon-material clause -- damage to items made of dragon
 *  material is fully reimbursed -- is therefore already honoured here: it grants
 *  exactly what the default grants, so no dragon branch is written. Should a
 *  future clause reduce reimbursement for some *other* reason, dragon material
 *  would have to be read as an exemption from it, and would then need a branch
 *  of its own. */
function reimbursedAmount(damage: Damage, item: Item): number {
  if (fallsUnderHighEnchantmentClause(item)) {
    return damage.amount * HIGH_ENCHANTMENT_CLAUSE_SHARE;
  }
  return damage.amount;
}

/** The handbook's reimbursement decision for one damage event: the clauses
 *  decide the reimbursed amount, from which the MHPCO keeps back its
 *  deductible. */
function reimbursementForDamage(damage: Damage, item: Item): number {
  return neverACharge(reimbursedAmount(damage, item) - DEDUCTIBLE_PER_DAMAGE);
}

/** One reported damage, matched to the covered item it refers to. */
interface MatchedDamage {
  damage: Damage;
  item: Item;
}

/** Whether the office entertains a reported damage at all, judged on the entry
 *  itself and without consulting the cover. A damage is a loss the customer
 *  suffered, so an entry claiming a negative amount is not an understated claim
 *  the office could settle at nothing -- it is not a damage report at all, and
 *  the office refuses the whole claim rather than reading past it.
 *
 *  This is the office's admission policy, and it is revised independently of how
 *  a report is read against the cover: a new ground of refusal is a rule added
 *  here, and a change to how damages are assigned to covered items leaves it
 *  untouched. */
function refuseInadmissibleDamage(damage: Damage): void {
  if (damage.amount < 0) {
    throw new Error(`a damage report cannot claim a negative amount of ${damage.amount} G`);
  }
}

/** Which covered item each reported damage refers to. The office reads a
 *  damage report against the policy's *cover*: a damage names an item type, and
 *  the office assigns it one of the items the policy covers of that type. Two
 *  entries of the same type are two damages against two covered swords, not the
 *  same sword claimed twice, so a matched item is struck off the cover and the
 *  next entry of that type must find another.
 *
 *  A report naming an item the policy does not cover, or naming more items of a
 *  type than the policy covers, fails here: that is a failure of the cover, not
 *  of the entry's own form, so an unmatchable entry stops the claim rather than
 *  being settled against nothing. */
function matchDamagesToCover(policy: Policy, damages: Damage[]): MatchedDamage[] {
  const unclaimedCover = [...policy.items];
  return damages.map((damage) => {
    const covered = unclaimedCover.findIndex((item) => item.type === damage.itemType);
    if (covered < 0) {
      throw new Error(
        `the policy covers no further ${damage.itemType} for this damage report`,
      );
    }
    const [item] = unclaimedCover.splice(covered, 1);
    return { damage, item };
  });
}

/** The damages of an incident the office admits to settlement: every entry is
 *  first judged admissible on its own terms, then read against the policy's
 *  cover. A report that fails either test is refused whole -- the office does
 *  not settle the admissible part of a bad report. */
function admitDamages(policy: Policy, damages: Damage[]): MatchedDamage[] {
  damages.forEach(refuseInadmissibleDamage);
  return matchDamagesToCover(policy, damages);
}

/** The sum a policy insures: the insurance values of all covered items. The
 *  block discount on the premium does not reduce what the items are insured
 *  for. */
function insuranceSum(policy: Policy): number {
  return policy.items.reduce((sum, item) => sum + insuranceValue(item), 0);
}

/** The most the MHPCO will ever pay out on a policy. */
function payoutCap(policy: Policy): number {
  return insuranceSum(policy) * CAP_MULTIPLE_OF_INSURANCE_SUM;
}

/** What the handbook reimburses for a whole incident: every admitted damage
 *  settled on its own terms -- its own clauses, its own deductible -- and the
 *  reimbursements added up. This is the claim before the cap is consulted; how
 *  far the policy's cap bounds it is a separate decision. */
function reimbursementForIncident(admitted: MatchedDamage[]): number {
  return admitted.reduce(
    (sum, { damage, item }) => sum + reimbursementForDamage(damage, item),
    0,
  );
}

/** What is left of a policy's cap: the cap itself, less what the MHPCO has
 *  already paid out on it. */
function remainingCap(policy: Policy): number {
  return payoutCap(policy) - policy.capConsumed;
}

/** What the MHPCO actually pays for an incident: what the handbook reimburses,
 *  but never more than the policy's cap still allows. A claim that asks for more
 *  than is left is settled at what is left. */
function settledPayout(policy: Policy, admitted: MatchedDamage[]): number {
  const bounded = Math.min(reimbursementForIncident(admitted), remainingCap(policy));
  return amountPaidInMHPCOsFavour(bounded);
}

/** The office's ledger entry against the policy: a settled payout consumes that
 *  much of the policy's cap, once and for good. This is what makes a claim a
 *  command rather than a calculation -- the cap a later claim finds is the cap
 *  this one left behind. */
function recordAgainstCap(policy: Policy, payout: number): void {
  policy.capConsumed += payout;
}

/** The MHPCO settles one incident against a policy: it decides what the claim is
 *  worth under the handbook and the policy's remaining cap, enters that payout
 *  in the policy's ledger, and reports the payout with the cap that survives it.
 *  Admitting the report against the cover comes first and on its own: a report
 *  the office refuses is refused before any amount is decided, so whether a
 *  claim is entertained at all changes independently of what it is worth.
 *  Deciding the amount and recording it are separate acts here, so that a change
 *  to how a payout is arrived at is necessarily also what gets recorded. */
export function claim(policy: Policy, incident: Incident): ClaimResult {
  const admitted = admitDamages(policy, incident.damages);
  const payout = settledPayout(policy, admitted);
  recordAgainstCap(policy, payout);
  return { payout, remainingCap: remainingCap(policy) };
}

